  const totalRevenue = numberField('TotalRevenue', 128_400_000);
  const totalOrders = numberField('TotalOrders', 1_284);
  const onlineOrders = numberField('TotalOnlineOrders', 734);
  const offlineOrders = numberField('TotalOfflineOrders', 550);
  const stats = [{ label: 'Total revenue', value: formatCompactMoney(totalRevenue), change: '+12.5%', icon: CircleDollarSign, tone: 'indigo' }, { label: 'Total orders', value: totalOrders.toLocaleString('vi-VN'), change: '+8.2%', icon: ShoppingBag, tone: 'blue' }, { label: 'Online orders', value: onlineOrders.toLocaleString('vi-VN'), change: '+14.8%', icon: ShoppingCart, tone: 'violet' }, { label: 'Offline orders', value: offlineOrders.toLocaleString('vi-VN'), change: '+3.1%', icon: Store, tone: 'amber' }];
