    <div className="mb-6 grid gap-5 xl:grid-cols-[1.45fr_1fr]"><Card><div className="flex items-center justify-between border-b border-zinc-100 px-5 py-4"><div><h2 className="font-display text-sm font-bold text-zinc-900">Revenue trend</h2><p className="mt-0.5 text-xs text-zinc-500">Daily revenue · September 2026</p></div><Badge tone="success">+12.5%</Badge></div><div className="h-[280px] p-4"><ResponsiveContainer width="100%" height="100%"><AreaChart data={revenue} margin={{ top: 12, right: 10, left: -18, bottom: 0 }}><defs><linearGradient id="revenue-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4f46e5" stopOpacity={0.2} /><stop offset="100%" stopColor="#4f46e5" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="#f1f1f4" vertical={false} /><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{ fontSize: 11, fill: '#a1a1aa' }} /><YAxis tickLine={false} axisLine={false} tick={{ fontSize: 11, fill: '#a1a1aa' }} tickFormatter={(v) => `${v}M`} /><Tooltip contentStyle={{ borderRadius: 10, border: '1px solid #e4e4e7', boxShadow: '0 8px 24px rgba(0,0,0,.08)', fontSize: 12 }} formatter={(v) => [`₫${Number(v).toFixed(1)}M`, 'Revenue']} /><Area type="monotone" dataKey="value" stroke="#4f46e5" strokeWidth={2.5} fill="url(#revenue-fill)" /></AreaChart></ResponsiveContainer></div></Card>
      <Card><div className="flex items-center justify-between border-b border-zinc-100 px-5 py-4"><div><h2 className="font-display text-sm font-bold text-zinc-900">Orders trend</h2><p className="mt-0.5 text-xs text-zinc-500">Online vs offline · this week</p></div><FilterButton>7 days</FilterButton></div><div className="h-[280px] p-4"><ResponsiveContainer width="100%" height="100%"><BarChart data={orderBars} margin={{ top: 12, right: 0, left: -22, bottom: 0 }}><CartesianGrid stroke="#f1f1f4" vertical={false} /><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{ fontSize: 11, fill: '#a1a1aa' }} /><YAxis tickLine={false} axisLine={false} tick={{ fontSize: 11, fill: '#a1a1aa' }} /><Tooltip cursor={{ fill: '#fafafa' }} contentStyle={{ borderRadius: 10, border: '1px solid #e4e4e7', fontSize: 12 }} /><Bar dataKey="online" stackId="orders" fill="#6366f1" radius={[3, 3, 0, 0]} name="Online" /><Bar dataKey="offline" stackId="orders" fill="#c4b5fd" radius={[3, 3, 0, 0]} name="Offline" /></BarChart></ResponsiveContainer></div><div className="flex justify-center gap-4 pb-4 text-[11px] font-semibold text-zinc-500"><span className="inline-flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-indigo-500" />Online</span><span className="inline-flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-indigo-200" />Offline</span></div></Card></div>
