function ListPage({ type }: { type: string }) { const configs: Record<string, { title: string; eyebrow: string; description: string; icon: typeof Tag; action: string; columns: string[]; rows: string[][] }> = { Categories: { title: 'Categories', eyebrow: 'Catalog', description: 'Organize products into clear, discoverable groups.', icon: Tag, action: 'Add category', columns: ['Name', 'Products', 'Created', 'Status', ''], rows: [['Drinks', '42', '12 Aug 2026', 'Active', ''], ['Food', '86', '12 Aug 2026', 'Active', ''], ['Snacks', '38', '12 Aug 2026', 'Active', '']] }, Suppliers: { title: 'Suppliers', eyebrow: 'Catalog', description: 'Keep supplier details and product sourcing in one place.', icon: Truck, action: 'Add supplier', columns: ['Supplier', 'Contact', 'Products', 'Status', ''], rows: [['ABC Trading', 'contact@abc.vn', '64', 'Active', ''], ['Saigon Wholesale', 'hello@saigon.vn', '102', 'Active', ''], ['Fresh Goods Co.', 'support@fresh.vn', '18', 'Inactive', '']] }, Promotions: { title: 'Promotions', eyebrow: 'Sales', description: 'Create and monitor discount campaigns across channels.', icon: TicketPercent, action: 'Create promotion', columns: ['Code', 'Discount', 'Usage', 'Period', 'Status', ''], rows: [['WELCOME10', '10%', '82 / 100', 'Sep 01 – Oct 01', 'Active', ''], ['FALL50K', '₫50,000', '30 / 50', 'Sep 15 – Sep 30', 'Active', ''], ['FREESHIP', '₫30,000', '1,240 / ∞', 'Aug 01 – Sep 30', 'Inactive', '']] }, Bills: { title: 'Bills', eyebrow: 'Finance', description: 'Review payment status and issue customer invoices.', icon: Receipt, action: 'Export bills', columns: ['Bill', 'Order', 'Customer', 'Amount', 'Status', ''], rows: [['#B-28392', '#10294', 'Nguyễn Văn A', '₫480,000', 'Paid', ''], ['#B-28391', '#10293', 'Lê Minh Anh', '₫128,000', 'Paid', ''], ['#B-28390', '#10292', 'Trần Quang Huy', '₫760,000', 'Unpaid', '']] }, Refunds: { title: 'Refund requests', eyebrow: 'Finance', description: 'Resolve refund requests with a clear, auditable workflow.', icon: RefreshCw, action: 'Export', columns: ['Request', 'Order', 'Customer', 'Amount', 'Status', ''], rows: [['#RF-1024', '#10222', 'Nguyễn Văn A', '₫320,000', 'Pending', ''], ['#RF-1023', '#10198', 'Phạm Thảo', '₫180,000', 'Approved', ''], ['#RF-1022', '#10176', 'Lê Minh Anh', '₫95,000', 'Completed', '']] } }; const config = configs[type] ?? configs.Categories; const [search, setSearch] = useState(''); const rows = config.rows.filter((r) => r.join(' ').toLowerCase().includes(search.toLowerCase())); return <><PageHeader eyebrow={config.eyebrow} title={config.title} description={config.description} action={<Button icon={config.icon}>{config.action}</Button>} />{type === 'Refunds' && <div className="mb-4 flex gap-2"><Badge tone="warning">Pending: 4</Badge><Badge tone="success">Completed this month: 28</Badge></div>}<Card><div className="border-b border-zinc-100 p-4"><Toolbar search={search} setSearch={setSearch} placeholder={`Search ${type.toLowerCase()}...`}><FilterButton>Status</FilterButton>{type === 'Refunds' && <FilterButton>All requests</FilterButton>}</Toolbar></div><div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left"><thead className="bg-zinc-50/80 text-[11px] uppercase tracking-wide text-zinc-400"><tr>{config.columns.map((h) => <th key={h} className="px-5 py-3 font-bold">{h}</th>)}</tr></thead><tbody className="divide-y divide-zinc-100">{rows.map((row) => <tr key={row[0]} className="text-sm hover:bg-zinc-50/60">{row.map((cell, i) => <td key={`${row[0]}-${i}`} className="px-5 py-4">{i === row.length - 1 ? <MoreHorizontal size={17} className="text-zinc-400" /> : i === config.columns.length - 2 ? <Status value={cell} /> : <span className={i === 0 ? 'font-semibold text-zinc-800' : 'text-zinc-500'}>{cell}</span>}</td>)}</tr>)}</tbody></table>{!rows.length && <EmptyState title={`No ${type.toLowerCase()} found`} copy="Clear filters or try another keyword." />}</div></Card></>; }
function AiPage({ page }: { page: string }) { const titles: Record<string, [string, string]> = { chat: ['AI Assistant', 'Ask questions about your store and get a cited operational answer.'], agents: ['Agents', 'Configure specialized operators and their allowed tools.'], runs: ['Agent runs', 'Observe model runs, tool calls and outcomes in one place.'], activity: ['Live activity', 'Follow tool execution and model events as they happen.'], reports: ['Reports', 'Generate sales and operational reports for your team.'], analytics: ['Agent analytics', 'Understand usage, reliability and tool performance.'], tools: ['Tools', 'Review the read-only tools available to agents.'] }; const [title, description] = titles[page] ?? titles.agents; if (page === 'chat') return <div className="-m-4 flex min-h-[calc(100vh-64px)] items-center justify-center bg-zinc-100/70 p-4 lg:-m-6 lg:p-6"><Card className="flex h-[min(720px,calc(100vh-110px))] w-full max-w-4xl flex-col overflow-hidden"><div className="flex items-center gap-3 border-b border-zinc-100 px-6 py-4"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-indigo-600 text-white"><Sparkles size={17} /></div><div><h1 className="font-display text-sm font-bold">Store Assistant</h1><p className="text-xs text-zinc-400">Read-only operations copilot</p></div><Badge tone="success">Online</Badge></div><div className="flex flex-1 flex-col items-center justify-center px-6 text-center"><div className="mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-indigo-50 text-indigo-600"><Sparkles size={24} /></div><h2 className="font-display text-2xl font-bold text-zinc-950">What can I find for you?</h2><p className="mt-2 max-w-md text-sm text-zinc-500">Ask about inventory, orders, sales trends or product performance.</p><div className="mt-7 grid w-full max-w-xl gap-2 sm:grid-cols-2"><button className="rounded-xl border border-zinc-200 bg-white p-3 text-left text-xs font-semibold text-zinc-600 hover:border-indigo-300 hover:bg-indigo-50">“Tồn kho mì gói hiện tại?”</button><button className="rounded-xl border border-zinc-200 bg-white p-3 text-left text-xs font-semibold text-zinc-600 hover:border-indigo-300 hover:bg-indigo-50">“Doanh thu tuần này so với tuần trước?”</button></div></div><div className="border-t border-zinc-100 p-4"><div className="flex items-center gap-2 rounded-xl border border-zinc-200 bg-zinc-50 px-4 py-3"><input placeholder="Ask about your store..." className="flex-1 bg-transparent text-sm outline-none" /><button className="flex h-8 w-8 items-center justify-center rounded-lg bg-zinc-950 text-white"><ArrowUpRight size={15} /></button></div><p className="mt-2 text-center text-[11px] text-zinc-400">AI answers use your store data. Check important decisions.</p></div></Card></div>;
  return <><PageHeader eyebrow="AI Operations" title={title} description={description} action={<Button icon={Plus}>{page === 'reports' ? 'Generate report' : page === 'agents' ? 'New agent' : 'Export'}</Button>} />{page === 'analytics' ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{ label: 'Total runs', value: '1,284' }, { label: 'Success rate', value: '96.8%' }, { label: 'Failed runs', value: '41' }, { label: 'Tool calls', value: '5,932' }].map(({ label, value }) => <Card key={label} className="p-5"><p className="text-xs font-semibold text-zinc-500">{label}</p><div className="mt-2 flex items-end justify-between"><b className="font-display text-2xl text-zinc-950">{value}</b><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-indigo-50 text-indigo-600"><Settings2 size={16} /></span></div></Card>)}</div> : <Card><div className="divide-y divide-zinc-100">{(page === 'agents' ? [['Sales Assistant', 'GPT-5 · 4 tools · 234 runs', 'Running'], ['Inventory Agent', 'GPT-5 · 3 tools · 108 runs', 'Running'], ['Customer Insights', 'GPT-4.1 · 5 tools · 86 runs', 'Paused']] : page === 'runs' ? [['Sales Assistant', 'RUN-00812 · 2m ago', 'Running'], ['Sales Assistant', 'RUN-00811 · 8m ago', 'Completed'], ['Inventory Agent', 'RUN-00810 · 14m ago', 'Failed']] : page === 'reports' ? [['Sales · September 2026', '01 Sep → 29 Sep · Revenue ₫128M', 'Ready'], ['Inventory health', '01 Sep → 29 Sep · 12 low-stock items', 'Ready']] : [['search_products', 'Search products and categories', 'Available'], ['get_stock', 'Read current inventory quantities', 'Available'], ['sales_summary', 'Read aggregated sales stats', 'Available']]).map((r) => <div key={`${r[0]}-${r[1]}`} className="flex flex-wrap items-center gap-4 px-5 py-4"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-indigo-50 text-indigo-600">{page === 'agents' ? <Sparkles size={16} /> : page === 'tools' ? <Settings2 size={16} /> : <Activity size={16} />}</div><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-zinc-800">{r[0]}</p><p className="text-xs text-zinc-400">{r[1]}</p></div><Status value={r[2]} /><button className="rounded p-1.5 text-zinc-400 hover:bg-zinc-100"><MoreHorizontal size={17} /></button></div>)}</div></Card>}</>; }
function AdminPage({ page }: { page: string }) { const map: Record<string, [string, string]> = { users: ['Staff', 'Manage store staff and assign roles.'], roles: ['Roles', 'Define role templates for your store team.'], permissions: ['Permissions', 'Review permission capabilities and role mappings.'] }; const [title, description] = map[page] ?? map.users; return <><PageHeader eyebrow="Administration" title={title} description={description} action={<Button icon={Plus}>{page === 'users' ? 'Add staff' : page === 'roles' ? 'New role' : 'Add permission'}</Button>} /><Card><div className="border-b border-zinc-100 p-4"><Toolbar search="" setSearch={() => undefined} placeholder={`Search ${title.toLowerCase()}...`}><FilterButton>All roles</FilterButton></Toolbar></div>{page === 'permissions' ? <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-zinc-50 text-[11px] uppercase tracking-wide text-zinc-400"><tr><th className="px-5 py-3">Permission</th><th className="px-5 py-3">Admin</th><th className="px-5 py-3">Manager</th><th className="px-5 py-3">Staff</th></tr></thead><tbody className="divide-y divide-zinc-100">{['Dashboard view', 'Customer manage', 'Product manage', 'Order manage', 'Inventory manage', 'Agent manage'].map((p, i) => <tr key={p}><td className="px-5 py-4 font-semibold text-zinc-700">{p}</td>{[0, 1, 2].map((r) => <td key={r} className="px-5 py-4"><button className={cx('flex h-5 w-5 items-center justify-center rounded border', r === 2 && i > 3 ? 'border-zinc-200 text-transparent' : 'border-indigo-600 bg-indigo-600 text-white')}><Check size={13} /></button></td>)}</tr>)}</tbody></table></div> : <div className="divide-y divide-zinc-100">{(page === 'users' ? [['Nguyễn Minh', 'minh@store.vn', 'Admin', 'Active'], ['Lê Hương', 'huong@store.vn', 'Manager', 'Active'], ['Trần Nam', 'nam@store.vn', 'Staff', 'Active']] : [['Admin', 'Full store access', '3 members', 'Active'], ['Manager', 'Sales + catalog', '1 member', 'Active'], ['Staff', 'POS only', '4 members', 'Active']]).map((r) => <div key={r[0]} className="flex items-center gap-3 px-5 py-4"><Avatar name={r[0]} /><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-zinc-800">{r[0]}</p><p className="text-xs text-zinc-400">{r.slice(1, -1).join(' · ')}</p></div><Status value={r[r.length - 1]} /><MoreHorizontal size={17} className="text-zinc-400" /></div>)}</div>}</Card></>; }
export const pages = { DashboardPage, OrdersPage, ProductsPage, InventoryPage, PosPage, CustomersPage, ListPage, AiPage, AdminPage };
export function PlaceholderPage({ title }: { title: string }) { return <PageHeader title={title} description="This workspace is ready for the next connected operation." action={<Button icon={Plus}>Create</Button>} />; }
export function OrderDetailPage() { const { id } = useParams(); return <OrdersPage />; }

export function AdminPages({ page }: { page: string }) {
  switch (page) {
    case 'dashboard': return <DashboardPage />;
    case 'orders': return <OrdersPage />;
    case 'orders-detail': return <OrderDetailPage />;
    case 'pos': return <PosPage />;
    case 'products': return <ProductsPage />;
    case 'inventory': return <InventoryPage />;
    case 'customers': return <CustomersPage />;
    case 'categories': return <ListPage type="Categories" />;
    case 'suppliers': return <ListPage type="Suppliers" />;
    case 'promotions': return <ListPage type="Promotions" />;
    case 'bills': return <ListPage type="Bills" />;
    case 'refunds': return <ListPage type="Refunds" />;
    case 'ai-chat': return <AiPage page="chat" />;
    case 'ai-agents':
    case 'ai-agents-detail': return <AiPage page="agents" />;
    case 'ai-runs':
    case 'ai-runs-detail': return <AiPage page="runs" />;
    case 'ai-activity': return <AiPage page="activity" />;
    case 'ai-reports': return <AiPage page="reports" />;
    case 'ai-analytics': return <AiPage page="analytics" />;
    case 'ai-tools': return <AiPage page="tools" />;
    case 'admin-users': return <AdminPage page="users" />;
    case 'admin-roles': return <AdminPage page="roles" />;
    case 'admin-permissions': return <AdminPage page="permissions" />;
    default: return <PlaceholderPage title="Page not found" />;
  }
}

export function LoginPage() {
  const auth = useAuth();
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent) {
    event.preventDefault();
    setError('');
    if (!username || !password) { setError('Enter your username and password.'); return; }
    if (!auth) { navigate('/dashboard'); return; }
    setBusy(true);
    try { await auth.login(username, password); navigate('/dashboard'); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to sign in.'); } finally { setBusy(false); }
  }
  return <div className="flex min-h-screen bg-zinc-950"><div className="hidden w-[46%] flex-col justify-between overflow-hidden bg-indigo-600 p-10 text-white lg:flex"><div><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-white/15"><Store size={20} /></span><span className="font-display text-lg font-bold">NOVA MART</span></div><div className="mt-[18vh] max-w-md"><p className="mb-4 text-xs font-bold uppercase tracking-[.18em] text-indigo-200">Store operations</p><h1 className="font-display text-5xl font-extrabold leading-[1.05] tracking-[-.04em]">Run your store with clarity.</h1><p className="mt-5 text-base leading-7 text-indigo-100">One calm workspace for orders, inventory, customers and the decisions behind them.</p></div></div><p className="text-xs text-indigo-200">© 2026 Nova Mart · Admin workspace</p></div><main className="flex flex-1 items-center justify-center bg-canvas p-6 sm:p-10"><div className="w-full max-w-[380px]"><div className="mb-10 lg:hidden"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-zinc-950 text-white"><Store size={20} /></span><span className="font-display text-lg font-bold">NOVA MART</span></div></div><div className="mb-8"><p className="mb-2 text-xs font-bold uppercase tracking-[.16em] text-indigo-600">Welcome back</p><h1 className="font-display text-3xl font-extrabold tracking-[-.03em] text-zinc-950">Sign in to admin</h1><p className="mt-2 text-sm text-zinc-500">Use your store account to continue.</p></div><form onSubmit={submit} className="space-y-4"><Field label="Username"><input value={username} onChange={(e) => setUsername(e.target.value)} autoComplete="username" placeholder="you@store.vn" className="h-11 w-full rounded-lg border border-zinc-200 bg-white px-3 text-sm outline-none focus:border-indigo-400 focus:ring-3 focus:ring-indigo-100" /></Field><Field label="Password"><input value={password} onChange={(e) => setPassword(e.target.value)} type="password" autoComplete="current-password" placeholder="Enter your password" className="h-11 w-full rounded-lg border border-zinc-200 bg-white px-3 text-sm outline-none focus:border-indigo-400 focus:ring-3 focus:ring-indigo-100" /></Field>{error && <p className="rounded-lg bg-red-50 px-3 py-2.5 text-xs font-medium text-red-700">{error}</p>}<Button className="mt-2 h-11 w-full" disabled={busy}>{busy ? 'Signing in…' : 'Sign in'}<ChevronRight size={16} /></Button></form><div className="mt-8 rounded-xl border border-indigo-100 bg-indigo-50 p-4 text-xs leading-5 text-indigo-800"><b>Local preview</b><br />The dashboard remains available without a live API. Sign in connects to `/api/auth/login` when the backend is running.</div></div></main></div>;
}
